var a = new Knoten(3);
var b = new Knoten(7);
var c = new Knoten(9);
a.Next = b;
b.Next = c;

Knoten? k = a;
while (k != null)
{
    Console.Write(k.Wert + " ");
    k = k.Next;
}
// Ausgabe: 3 7 9

class Knoten
{
    public int Wert;
    public Knoten? Next;
    public Knoten(int wert) => Wert = wert;
}

var liste = new EinfachListe();
liste.AddLast(7);
liste.AddLast(9);
liste.AddFirst(3);
liste.Ausgeben();
// Ausgabe: 3 7 9

class EinfachListe
{
    private Knoten? kopf;

    public void AddFirst(int wert)
    {
        var neu = new Knoten(wert);
        neu.Next = kopf;
        kopf = neu;
    }

    public void AddLast(int wert)
    {
        var neu = new Knoten(wert);
        if (kopf == null)
        {
            kopf = neu;
            return;
        }
        Knoten k = kopf;
        while (k.Next != null)
            k = k.Next;
        k.Next = neu;
    }

    public void Ausgeben()
    {
        var k = kopf;
        while (k != null)
        {
            Console.Write(k.Wert + " ");
            k = k.Next;
        }
        Console.WriteLine();
    }
}

// in der Klasse EinfachListe:
public bool Remove(int wert)
{
    if (kopf == null) return false;
    if (kopf.Wert == wert)
    {
        kopf = kopf.Next; // 1. Knoten
        return true;
    }
    Knoten k = kopf;
    while (k.Next != null)
    {
        if (k.Next.Wert == wert)
        {
            // Nachfolger überspringen
            k.Next = k.Next.Next;
            return true;
        }
        k = k.Next;
    }
    return false;
}

var zug = new LinkedList<string>();
zug.AddLast("Lok");
zug.AddLast("Wagen 1");
zug.AddLast("Wagen 2");

LinkedListNode<string> lok = zug.First!;
zug.AddAfter(lok, "Speisewagen");
zug.Remove("Wagen 1");
zug.AddFirst("Schublok");

Console.WriteLine(string.Join(", ", zug));
var v = zug.Last!.Previous!;
Console.WriteLine(v.Value);
// Ausgabe:
// Schublok, Lok, Speisewagen, Wagen 2
// Speisewagen

